using Avalonia;
using Avalonia.Controls;
using Avalonia.Controls.Primitives;
using Avalonia.Layout;
using Avalonia.LogicalTree;

namespace Alta.Themes.Controls;

public enum ToolTipSeverity
{
    Info,
    Success,
    Warning,
    Error
}

public class ArrowToolTip : ContentControl
{
    private const double DefaultRenderScale = 1d;
    private const double AlignmentZoneDivisor = 3d;
    private const double HorizontalArrowTipOffset = 22d;
    private const double VerticalArrowTipOffSet = 24d;

    public enum Placement
    {
        Top,
        Bottom,
        Left,
        Right
    }

    public static readonly StyledProperty<string?> HeaderTextProperty =
        AvaloniaProperty.Register<ArrowToolTip, string?>(nameof(HeaderText));

    public static readonly StyledProperty<string?> TextProperty =
        AvaloniaProperty.Register<ArrowToolTip, string?>(nameof(Text));

    public static readonly StyledProperty<string?> HintTextProperty =
        AvaloniaProperty.Register<ArrowToolTip, string?>(nameof(HintText));

    public static readonly StyledProperty<ToolTipSeverity?> SeverityProperty =
        AvaloniaProperty.Register<ArrowToolTip, ToolTipSeverity?>(nameof(Severity));

    public static readonly StyledProperty<Placement?> PositionProperty =
        AvaloniaProperty.Register<ArrowToolTip, Placement?>(nameof(Position));

    public static readonly StyledProperty<VerticalAlignment> ArrowVerticalAlignmentProperty =
        AvaloniaProperty.Register<ArrowToolTip, VerticalAlignment>(nameof(ArrowVerticalAlignment));

    public static readonly StyledProperty<HorizontalAlignment> ArrowHorizontalAlignmentProperty =
        AvaloniaProperty.Register<ArrowToolTip, HorizontalAlignment>(nameof(ArrowHorizontalAlignment));

    public static readonly StyledProperty<IEnumerable<object>?> ItemsSourceProperty =
        AvaloniaProperty.Register<ArrowToolTip, IEnumerable<object>?>(nameof(ItemsSource));

    public string? HeaderText
    {
        get => GetValue(HeaderTextProperty);
        set => SetValue(HeaderTextProperty, value);
    }

    public string? Text
    {
        get => GetValue(TextProperty);
        set => SetValue(TextProperty, value);
    }

    public string? HintText
    {
        get => GetValue(HintTextProperty);
        set => SetValue(HintTextProperty, value);
    }

    public ToolTipSeverity? Severity
    {
        get => GetValue(SeverityProperty);
        set => SetValue(SeverityProperty, value);
    }

    public Placement? Position
    {
        get => GetValue(PositionProperty);
        set => SetValue(PositionProperty, value);
    }

    public VerticalAlignment ArrowVerticalAlignment
    {
        get => GetValue(ArrowVerticalAlignmentProperty);
        set => SetValue(ArrowVerticalAlignmentProperty, value);
    }

    public HorizontalAlignment ArrowHorizontalAlignment
    {
        get => GetValue(ArrowHorizontalAlignmentProperty);
        set => SetValue(ArrowHorizontalAlignmentProperty, value);
    }

    public IEnumerable<object>? ItemsSource
    {
        get => GetValue(ItemsSourceProperty);
        set => SetValue(ItemsSourceProperty, value);
    }

    public ArrowToolTip()
    {
        PropertyChanged += (_, e) =>
        {
            if (e.Property.Name == nameof(ItemsSource))
            {
                if (ItemsSource is not null)
                {
                    int count = 0;
                    foreach (var val in ItemsSource)
                    {
                        if (count == 0) HeaderText = val.ToString();
                        else if (count == 1) Text = val.ToString();
                        else if (count == 2) HintText = val.ToString();
                        count++;
                    }
                }
            }
        };

        Loaded += (_, _) =>
        {
            var popup = this.FindLogicalAncestorOfType<Popup>();

            if (popup is null)
                return;
            if (popup.Placement == PlacementMode.Pointer)
            {
                Position = Placement.Bottom;
                ArrowHorizontalAlignment = HorizontalAlignment.Left;
                popup.HorizontalOffset -= VerticalArrowTipOffSet;
                return;
            }

            if (popup.PlacementTarget is not { } adorned) return;
            var scale = TopLevel.GetTopLevel(this)?.RenderScaling ?? DefaultRenderScale;
            scale = scale <= 0 ? DefaultRenderScale : scale;
            popup.VerticalOffset = 0;

            var tlToolTipPosition = this.PointToScreen(new Point(0,0));
            var brToolTipPosition = this.PointToScreen(new Point(Bounds.Width, Bounds.Height));

            var tlAdornedPosition = adorned.PointToScreen(new Point(0, 0));
            var brAdornedPosition = adorned.PointToScreen(new Point(adorned.Bounds.Width, adorned.Bounds.Height));

            if (tlToolTipPosition.X >= brAdornedPosition.X)
            {
                Position = Placement.Right;
            }
            else if (brToolTipPosition.X <= tlAdornedPosition.X)
            {
                Position = Placement.Left;
            }
            else if (brToolTipPosition.Y <= brAdornedPosition.Y)
            {
                Position = Placement.Top;
            }
            else if (tlToolTipPosition.Y >= tlAdornedPosition.Y)
            {
                Position = Placement.Bottom;
            }

            if (Position is Placement.Top or Placement.Bottom)
            {
                ArrowVerticalAlignment = VerticalAlignment.Center;
                var adornedScreenWidth = Math.Abs(brAdornedPosition.X - tlAdornedPosition.X);
                var elementCenter = tlAdornedPosition.X + adornedScreenWidth / 2;
                var ttThird = Math.Abs(tlToolTipPosition.X - brToolTipPosition.X) / AlignmentZoneDivisor;
                var leftBar = tlToolTipPosition.X + ttThird;
                var rightBar = brToolTipPosition.X - ttThird;

                if (elementCenter > leftBar && elementCenter < rightBar)
                {
                    ArrowHorizontalAlignment = HorizontalAlignment.Center;
                    var position = (elementCenter - tlToolTipPosition.X) / scale;
                    popup.HorizontalOffset = position - Bounds.Width / 2;
                }
                else if (elementCenter >= rightBar)
                {
                    ArrowHorizontalAlignment = HorizontalAlignment.Right;
                    var position = (elementCenter - brToolTipPosition.X) / scale;
                    popup.HorizontalOffset = position + HorizontalArrowTipOffset;
                }
                else
                {
                    ArrowHorizontalAlignment = HorizontalAlignment.Left;
                    var position = (elementCenter - tlToolTipPosition.X) / scale;
                    popup.HorizontalOffset = position - HorizontalArrowTipOffset;
                }
            }

            if (Position is Placement.Left or Placement.Right)
            {
                ArrowHorizontalAlignment = HorizontalAlignment.Center;
                var adornedScreenHeight = Math.Abs(brAdornedPosition.Y - tlAdornedPosition.Y);
                var elementCenter = tlAdornedPosition.Y + adornedScreenHeight / 2;
                var ttThird = Math.Abs(brToolTipPosition.Y - tlToolTipPosition.Y) / AlignmentZoneDivisor;
                var topBar = tlToolTipPosition.Y + ttThird;
                var bottomBar = brToolTipPosition.Y - ttThird;

                if (elementCenter > topBar && elementCenter < bottomBar)
                {
                    ArrowVerticalAlignment = VerticalAlignment.Center;
                    var position = (elementCenter - tlToolTipPosition.Y) / scale;
                    popup.VerticalOffset = position - Bounds.Height / 2;
                }
                else if (elementCenter <= topBar)
                {
                    ArrowVerticalAlignment = VerticalAlignment.Top;
                    var position = (elementCenter - tlToolTipPosition.Y) / scale;
                    popup.VerticalOffset = position - VerticalArrowTipOffSet;
                }
                else
                {
                    ArrowVerticalAlignment = VerticalAlignment.Bottom;
                    var position = (elementCenter - brToolTipPosition.Y) / scale;
                    popup.VerticalOffset = position + VerticalArrowTipOffSet;
                }
            }
        };
    }
}

using Avalonia;
using Avalonia.Controls;
using Avalonia.Input;
using Avalonia.Interactivity;
using Avalonia.Xaml.Interactivity;

namespace Alta.Themes.Controls.Behaviors;

/// <summary>
/// Выделяет весь текст TextBox при получении фокуса.
/// Глобально включается через attached-свойство SelectAllOnFocus чтобы не конфликтовать с локальными behaviors.
/// </summary>
public sealed class TextBoxSelectAllBehavior : Behavior<TextBox>
{
    public static readonly AttachedProperty<bool> SelectAllOnFocusProperty =
        AvaloniaProperty.RegisterAttached<TextBoxSelectAllBehavior, TextBox, bool>("SelectAllOnFocus");

    static TextBoxSelectAllBehavior()
    {
        SelectAllOnFocusProperty.Changed.AddClassHandler<TextBox>(OnSelectAllOnFocusChanged);
    }

    public static bool GetSelectAllOnFocus(TextBox textBox) =>
        textBox.GetValue(SelectAllOnFocusProperty);

    public static void SetSelectAllOnFocus(TextBox textBox, bool value) =>
        textBox.SetValue(SelectAllOnFocusProperty, value);

    private static void OnSelectAllOnFocusChanged(TextBox textBox, AvaloniaPropertyChangedEventArgs args)
    {
        if (args.GetNewValue<bool>())
        {
            textBox.AddHandler(InputElement.GotFocusEvent, OnTextBoxGotFocus, RoutingStrategies.Bubble);
            textBox.AddHandler(InputElement.PointerPressedEvent, OnTextBoxPointerPressed, RoutingStrategies.Tunnel);
        }
        else
        {
            textBox.RemoveHandler(InputElement.GotFocusEvent, OnTextBoxGotFocus);
            textBox.RemoveHandler(InputElement.PointerPressedEvent, OnTextBoxPointerPressed);
        }
    }

    private static void OnTextBoxGotFocus(object? sender, FocusChangedEventArgs args)
    {
        if (sender is TextBox textBox)
            textBox.SelectAll();
    }

    private static void OnTextBoxPointerPressed(object? sender, PointerPressedEventArgs args)
    {
        if (sender is not TextBox textBox || textBox.IsKeyboardFocusWithin)
            return;

        textBox.Focus();
        args.Handled = true;
    }

    protected override void OnAttached()
    {
        base.OnAttached();
        if (AssociatedObject is not null && !GetSelectAllOnFocus(AssociatedObject))
            SetSelectAllOnFocus(AssociatedObject, true);
    }
}

